--// TLX MM2 COPY HUB
--// Interface visual renovada para uso no Roblox Studio

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")

local LocalPlayer = Players.LocalPlayer
local KEY = "Rlltxw"

local ESP_ENABLED = true
local NOCLIP_ENABLED = false
local INFINITE_JUMP_ENABLED = false

local ESP = {}

--==================================================
-- DETECTAR PAPEL PELA ARMA/FACA
--==================================================

local function getRole(player)
    local backpack = player:FindFirstChild("Backpack")

    if backpack then
        if backpack:FindFirstChild("Knife") then
            return "Murderer"
        end

        if backpack:FindFirstChild("Gun") then
            return "Sheriff"
        end
    end

    local character = player.Character

    if character then
        if character:FindFirstChild("Knife") then
            return "Murderer"
        end

        if character:FindFirstChild("Gun") then
            return "Sheriff"
        end
    end

    return "Innocent"
end

--==================================================
-- REMOVER ESP
--==================================================

local function removeESP(player)
    if ESP[player] then
        ESP[player]:Destroy()
        ESP[player] = nil
    end
end

--==================================================
-- ATUALIZAR ESP
--==================================================

local function updateESP(player)
    if player == LocalPlayer then
        return
    end

    local character = player.Character

    if not character then
        removeESP(player)
        return
    end

    if not ESP_ENABLED then
        if ESP[player] then
            ESP[player].Enabled = false
        end
        return
    end

    local highlight = ESP[player]

    if not highlight or highlight.Parent ~= character then
        if highlight then
            highlight:Destroy()
        end

        highlight = Instance.new("Highlight")
        highlight.Name = "TLXRoleESP"
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.FillTransparency = 0.45
        highlight.OutlineTransparency = 0
        highlight.Parent = character

        ESP[player] = highlight
    end

    local role = getRole(player)

    highlight.Enabled = true

    if role == "Murderer" then
        highlight.FillColor = Color3.fromRGB(239, 68, 68)
        highlight.OutlineColor = Color3.fromRGB(248, 113, 113)
    elseif role == "Sheriff" then
        highlight.FillColor = Color3.fromRGB(59, 130, 246)
        highlight.OutlineColor = Color3.fromRGB(96, 165, 250)
    else
        highlight.FillColor = Color3.fromRGB(34, 197, 94)
        highlight.OutlineColor = Color3.fromRGB(74, 222, 128)
    end
end

--==================================================
-- LOOP ESP
--==================================================

task.spawn(function()
    while task.wait(0.2) do
        for _, player in ipairs(Players:GetPlayers()) do
            updateESP(player)
        end
    end
end)

Players.PlayerRemoving:Connect(function(player)
    removeESP(player)
end)

local function setupPlayer(player)
    if player == LocalPlayer then
        return
    end

    player.CharacterAdded:Connect(function()
        removeESP(player)
        task.wait(0.5)
        updateESP(player)
    end)

    player.CharacterRemoving:Connect(function()
        removeESP(player)
    end)

    if player.Character then
        task.spawn(function()
            task.wait(0.5)
            updateESP(player)
        end)
    end
end

for _, player in ipairs(Players:GetPlayers()) do
    setupPlayer(player)
end

Players.PlayerAdded:Connect(setupPlayer)

--==================================================
-- NOCLIP
--==================================================

local function setNoclip(enabled)
    NOCLIP_ENABLED = enabled

    local character = LocalPlayer.Character

    if not character then
        return
    end

    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            part.CanCollide = not enabled
        end
    end
end

RunService.Stepped:Connect(function()
    if not NOCLIP_ENABLED then
        return
    end

    local character = LocalPlayer.Character

    if character then
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = false
            end
        end
    end
end)

--==================================================
-- INFINITE JUMP
--==================================================

UserInputService.JumpRequest:Connect(function()
    if not INFINITE_JUMP_ENABLED then
        return
    end

    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

    if humanoid then
        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
    end
end)

